//! `DateInterval` construction, `createFromDateString()`, property handlers, `format()` and `__set_state()`
//! against PHP 8.5.13 (`tests/vectors/interval.json`, generated by `interval.gen.php`; regenerate with
//! `crates/twig-date/tests/vectors/regen.sh interval`).

mod common;

use common::*;
use serde_json::Value as Json;
use twig_date::interval::date_interval_create_from_date_string;
use twig_date::{DateObject, IntervalObject, TimeZoneObject, classes};
use twig_value::object::{FetchMode, PropertyCheck};
use twig_value::{Array, ObjectRef, Value, convert};

fn array_json(o: &ObjectRef) -> Json {
    to_json(&Value::Array(
        convert::to_array(&Value::Object(o.clone()), &mut Vec::new()).unwrap(),
    ))
}

fn fmt(o: &ObjectRef, f: &str) -> Json {
    Json::String(str_val(
        &call(o, "format", vec![php_str(f)], &mut Vec::new()).unwrap(),
    ))
}

#[test]
fn construct() {
    let v = load("interval");
    let c = Ctx::new();
    let mut r = Report::new("new DateInterval()");
    for case in v["construct"].as_array().unwrap() {
        let spec = bytes(&case[0]);
        let got = match IntervalObject::construct(&c.ctx, &spec) {
            Ok(o) => array_json(&o),
            Err(e) => Json::String(exc(&e)),
        };
        r.eq(got, case[1].clone(), || format!("{case}"));
    }
    r.finish();
}

#[test]
fn from_string() {
    let v = load("interval");
    let c = Ctx::new();
    let mut r = Report::new("createFromDateString()");
    for case in v["from_string"].as_array().unwrap() {
        let spec = bytes(&case[0]);
        let got = match IntervalObject::create_from_date_string(&c.ctx, &spec) {
            Ok(o) => {
                let mut row = vec![array_json(&o), fmt(&o, "%y %m %d %h %i %s %f %R %a")];
                for p in ["y", "m", "d", "days", "f"] {
                    let v = o
                        .read_property(p.as_bytes(), FetchMode::Read, &mut Vec::new())
                        .unwrap();
                    row.push(to_json(&v));
                }
                Json::Array(row)
            }
            Err(e) => Json::String(exc(&e)),
        };
        r.eq(got, case[1].clone(), || format!("{case}"));
        let mut diags = Vec::new();
        let f = match date_interval_create_from_date_string(&c.ctx, &spec, &mut diags).unwrap() {
            Some(o) => array_json(&o),
            None => Json::Bool(false),
        };
        r.eq(f, case[2].clone(), || format!("procedural {case}"));
        r.eq(Json::from(diag_strings(&diags)), case[3].clone(), || {
            format!("diagnostics {case}")
        });
    }
    r.finish();
}

fn utc(c: &Ctx, s: &str) -> ObjectRef {
    let tz = TimeZoneObject::construct(&c.ctx, b"UTC").unwrap();
    DateObject::construct(&c.ctx, classes::datetime(), s.as_bytes(), Some(&tz)).unwrap()
}

fn make(c: &Ctx, spec: &str) -> ObjectRef {
    if spec == "diff" {
        let a = utc(c, "2024-01-01");
        let b = utc(c, "2023-11-15 12:30:00.25");
        return obj(call(&a, "diff", vec![Value::Object(b)], &mut Vec::new()).unwrap());
    }
    if let Some(d) = spec.strip_prefix("diff:") {
        let (a, b) = d.split_once('|').unwrap();
        let (a, b) = (utc(c, a), utc(c, b));
        return obj(call(&a, "diff", vec![Value::Object(b)], &mut Vec::new()).unwrap());
    }
    if let Some(s) = spec.strip_prefix("str:") {
        return IntervalObject::create_from_date_string(&c.ctx, s.as_bytes()).unwrap();
    }
    IntervalObject::construct(&c.ctx, spec.as_bytes()).unwrap()
}

#[test]
fn format() {
    let v = load("interval");
    let c = Ctx::new();
    let mut r = Report::new("DateInterval::format()");
    for case in v["format"].as_array().unwrap() {
        let iv = make(&c, s(&case[0]));
        let f = bytes(&case[1]);
        let got = iv
            .downcast_ref::<IntervalObject>()
            .unwrap()
            .format(&f)
            .unwrap();
        r.eq(enc(got.as_bytes()), s(&case[2]).to_owned(), || {
            format!("{case}")
        });
    }
    r.finish();
}

/// A generator value as a PHP value (scalars only).
fn php_value(v: &Json) -> Value {
    match v {
        Json::Null => Value::Null,
        Json::Bool(b) => Value::Bool(*b),
        Json::Number(n) => match n.as_i64() {
            Some(i) => Value::Int(i),
            None => Value::Float(n.as_f64().unwrap()),
        },
        Json::String(s) => Value::from(s.as_str()),
        other => panic!("unsupported {other}"),
    }
}

#[test]
fn properties() {
    let v = load("interval");
    let c = Ctx::new();
    let mut r = Report::new("DateInterval properties");
    for case in v["props"].as_array().unwrap() {
        let (spec, op, name) = (s(&case[0]), s(&case[1]), s(&case[2]));
        let iv = make(&c, spec);
        let n = name.as_bytes();
        let mut diags = Vec::new();
        let got = match op {
            "get" => to_json(&iv.read_property(n, FetchMode::Read, &mut diags).unwrap()),
            "isset" => Json::Bool(
                iv.has_property(n, PropertyCheck::Isset, &mut diags)
                    .unwrap(),
            ),
            "empty" => Json::Bool(
                !iv.has_property(n, PropertyCheck::NotEmpty, &mut diags)
                    .unwrap(),
            ),
            "exists" => Json::Bool(iv.property_exists(n, &mut diags).unwrap()),
            "set" => {
                iv.write_property(n, php_value(&case[3]), &mut diags)
                    .unwrap();
                Json::Array(vec![
                    array_json(&iv),
                    fmt(&iv, "%y %m %d %h %i %s %f %R %a"),
                ])
            }
            "after_cast" => {
                let before = match iv
                    .has_property(n, PropertyCheck::Isset, &mut diags)
                    .unwrap()
                {
                    true => to_json(&iv.read_property(n, FetchMode::Read, &mut diags).unwrap()),
                    false => Json::String("unset".to_owned()),
                };
                let before = Json::Array(vec![before, Json::from(diag_strings(&diags))]);
                diags.clear();
                let _ = array_json(&iv);
                let after = to_json(&iv.read_property(n, FetchMode::Read, &mut diags).unwrap());
                let isset = iv
                    .has_property(b"date_string", PropertyCheck::Isset, &mut diags)
                    .unwrap();
                Json::Array(vec![before, after, Json::Bool(isset)])
            }
            other => panic!("op {other}"),
        };
        r.eq(got, case[4].clone(), || format!("{case}"));
        r.eq(Json::from(diag_strings(&diags)), case[5].clone(), || {
            format!("diagnostics {case}")
        });
    }
    r.finish();
}

/// The `__set_state()` input arrays of the generator, rebuilt (JSON objects; `{}` is a `stdClass`).
fn state_array(j: &Json) -> Array {
    let mut a = Array::new();
    if let Json::Object(m) = j {
        for (k, v) in m {
            let val = match v {
                Json::Array(items) => Value::Array(Array::from_values(items.iter().map(php_value))),
                Json::Object(o) if o.is_empty() => {
                    Value::Object(twig_value::object::StdClass::new().into_ref())
                }
                other => php_value(other),
            };
            a.insert(k.as_str(), val);
        }
    }
    a
}

#[test]
fn set_state() {
    let v = load("interval");
    let c = Ctx::new();
    let mut r = Report::new("DateInterval::__set_state()");
    let proto = IntervalObject::construct(&c.ctx, b"P1D").unwrap();
    for case in v["state"].as_array().unwrap() {
        let input: Json = serde_json::from_str(s(&case[0])).unwrap();
        let mut diags = Vec::new();
        let got = match call(
            &proto,
            "__set_state",
            vec![Value::Array(state_array(&input))],
            &mut diags,
        ) {
            Ok(o) => {
                let o = obj(o);
                (array_json(&o), fmt(&o, "%y %m %d %h %i %s %f %R %a"))
            }
            Err(e) => (Json::String(exc(&e)), Json::Null),
        };
        r.eq(got.0, case[1].clone(), || format!("{case}"));
        r.eq(got.1, case[2].clone(), || format!("format {case}"));
        r.eq(Json::from(diag_strings(&diags)), case[3].clone(), || {
            format!("diagnostics {case}")
        });
    }
    r.finish();
}
